import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import type { Warga, Dukuh, RT } from '@/types';
import { getAllWarga, getAllDukuh, getAllRT, createWarga, updateWarga, deleteWarga, bulkCreateWarga } from '@/services/api';
import Modal from '@/components/Modal';
import { TrashIcon, PencilIcon, SearchIcon, QrCodeIcon, DownloadIcon, UploadIcon, FileExcelIcon, CheckCircleIcon, XIcon } from '@/components/icons';
import { QRCodeSVG } from 'qrcode.react';
import { exportToExcel, readWargaExcel } from '@/services/excel';

const WargaForm: React.FC<{
  warga?: Warga | null;
  dukuhList: Dukuh[];
  rtList: RT[];
  onSave: (warga: Omit<Warga, 'id' | 'totalDebt'> | Warga) => void;
  onCancel: () => void;
}> = ({ warga, dukuhList, rtList, onSave, onCancel }) => {
  const [formData, setFormData] = useState({
    name: warga?.name || '',
    dukuhId: warga?.dukuhId || (dukuhList[0]?.id || 0),
    rtId: warga?.rtId || (rtList[0]?.id || 0),
    dailyFee: warga?.dailyFee || 2000,
  });

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSave(warga ? { ...warga, ...formData } : formData); }} className="space-y-6">
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nama Lengkap Warga</label>
        <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none transition-all font-semibold" placeholder="Nama Warga" required />
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Dukuh</label>
          <select value={formData.dukuhId} onChange={e => setFormData({...formData, dukuhId: Number(e.target.value)})} className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-semibold">
            {dukuhList.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">RT</label>
          <select value={formData.rtId} onChange={e => setFormData({...formData, rtId: Number(e.target.value)})} className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-semibold">
            {rtList.map(rt => <option key={rt.id} value={rt.id}>RT {rt.number}</option>)}
          </select>
        </div>
      </div>
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tarif Iuran Harian</label>
        <div className="relative">
            <span className="absolute left-5 top-1/2 -translate-y-1/2 font-bold text-slate-400">Rp</span>
            <input type="number" value={formData.dailyFee} onChange={e => setFormData({...formData, dailyFee: Number(e.target.value)})} className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-bold" required />
        </div>
      </div>
      <div className="flex gap-3 pt-4">
        <button type="button" onClick={onCancel} className="flex-1 py-3.5 rounded-2xl font-bold text-slate-500 hover:bg-slate-100 transition-all">Batal</button>
        <button type="submit" className="flex-1 py-3.5 rounded-2xl font-bold bg-primary text-white hover:bg-primary-focus shadow-lg shadow-primary/20 transition-all">Simpan Data</button>
      </div>
    </form>
  );
};

const AdminWargaPage: React.FC = () => {
    const [wargaList, setWargaList] = useState<Warga[]>([]);
    const [dukuhList, setDukuhList] = useState<Dukuh[]>([]);
    const [rtList, setRtList] = useState<RT[]>([]);
    const [loading, setLoading] = useState(true);

    // States for Import Modal
    const [importLoading, setImportLoading] = useState(false);
    const [importReview, setImportReview] = useState<{
        valid: Omit<Warga, 'id' | 'totalDebt'>[],
        invalidCount: number,
        total: number,
        idErrors: boolean
    } | null>(null);

    const [filters, setFilters] = useState({ search: '', dukuhId: 'all', rtId: 'all' });
    const [sortConfig, setSortConfig] = useState<{ key: keyof Warga | 'address'; direction: 'asc' | 'desc' }>({ key: 'name', direction: 'asc' });
    const [itemsPerPage, setItemsPerPage] = useState<number | 'all'>(10);
    const [currentPage, setCurrentPage] = useState(1);

    const [isFormModalOpen, setIsFormModalOpen] = useState(false);
    const [selectedWarga, setSelectedWarga] = useState<Warga | null>(null);
    const [qrToShow, setQrToShow] = useState<Warga | null>(null);
    const [wargaToDelete, setWargaToDelete] = useState<Warga | null>(null);

    const fileInputRef = useRef<HTMLInputElement>(null);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [w, d, r] = await Promise.all([getAllWarga(), getAllDukuh(), getAllRT()]);
            setWargaList(w);
            setDukuhList(d);
            setRtList(r);
        } catch (err) {
            console.error("Error loading data", err);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { fetchData(); }, [fetchData]);

    const handleSort = (key: keyof Warga | 'address') => {
        let direction: 'asc' | 'desc' = 'asc';
        if (sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
        setSortConfig({ key, direction });
    };

    const sortedAndFilteredWarga = useMemo(() => {
        let items = wargaList.filter(w => {
            const matchSearch = (w.name || '').toLowerCase().includes(filters.search.toLowerCase()) || (w.id || '').includes(filters.search);
            const matchDukuh = filters.dukuhId === 'all' || w.dukuhId === Number(filters.dukuhId);
            const matchRT = filters.rtId === 'all' || w.rtId === Number(filters.rtId);
            return matchSearch && matchDukuh && matchRT;
        });

        return items.sort((a, b) => {
            let aVal: any, bVal: any;
            if (sortConfig.key === 'address') {
                const dukuhA = dukuhList.find(d => d.id === a.dukuhId)?.name || '';
                const dukuhB = dukuhList.find(d => d.id === b.dukuhId)?.name || '';
                aVal = dukuhA + (rtList.find(r => r.id === a.rtId)?.number || '');
                bVal = dukuhB + (rtList.find(r => r.id === b.rtId)?.number || '');
            } else {
                aVal = a[sortConfig.key as keyof Warga];
                bVal = b[sortConfig.key as keyof Warga];
            }

            if (typeof aVal === 'string') {
                return sortConfig.direction === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
            }
            return sortConfig.direction === 'asc' ? aVal - bVal : bVal - aVal;
        });
    }, [wargaList, filters, sortConfig, dukuhList, rtList]);

    const paginatedWarga = useMemo(() => {
        if (itemsPerPage === 'all') return sortedAndFilteredWarga;
        const start = (currentPage - 1) * (itemsPerPage as number);
        return sortedAndFilteredWarga.slice(start, start + (itemsPerPage as number));
    }, [sortedAndFilteredWarga, itemsPerPage, currentPage]);

    const totalPages = itemsPerPage === 'all' ? 1 : Math.ceil(sortedAndFilteredWarga.length / (itemsPerPage as number));

    // --- IMPORT LOGIC ---

    const handleDownloadTemplate = () => {
        const templateData = [
            { "Nama": "Budi Santoso", "Tarif": 2000, "Kode Dukuh": 1, "Kode RT": 1 },
            { "Nama": "Siti Aminah", "Tarif": 2500, "Kode Dukuh": 1, "Kode RT": 2 },
        ];
        exportToExcel(templateData, "Template_Warga_Rowosari", "DataWarga");
    };

    const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setImportLoading(true);
        try {
            const rawData = await readWargaExcel(file);

            const valid: Omit<Warga, 'id' | 'totalDebt'>[] = [];
            let invalidCount = 0;
            let foundIdErrors = false;

            // Buat Set ID wilayah yang ada di sistem untuk pencarian cepat (O(1))
            const existingDukuhIds = new Set(dukuhList.map(d => d.id));
            const existingRtIds = new Set(rtList.map(r => r.id));

            rawData.forEach(row => {
                const hasName = !!row.name && row.name.toString().trim().length >= 1;
                const hasFee = row.dailyFee !== undefined && !isNaN(Number(row.dailyFee));

                // Cek apakah ID wilayah ada di sistem (database)
                const dId = Number(row.dukuhId);
                const rId = Number(row.rtId);
                const isDukuhValid = !isNaN(dId) && existingDukuhIds.has(dId);
                const isRtValid = !isNaN(rId) && existingRtIds.has(rId);

                if (hasName && hasFee && isDukuhValid && isRtValid) {
                    valid.push(row as any);
                } else {
                    invalidCount++;
                    if (!isDukuhValid || !isRtValid) foundIdErrors = true;
                }
            });

            setImportReview({
                valid,
                invalidCount,
                total: rawData.length,
                idErrors: foundIdErrors
            });
        } catch (err: any) { 
            const errorMsg = err instanceof Error ? err.message : String(err);
            alert("Gagal membaca Excel: " + errorMsg); 
        } finally { 
            setImportLoading(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    const confirmImport = async () => {
        if (!importReview || importReview.valid.length === 0) return;

        setImportLoading(true);
        try {
            await bulkCreateWarga(importReview.valid);
            await fetchData();
            alert(`Berhasil mengimpor ${importReview.valid.length} warga.`);
            setImportReview(null);
        } catch (err: any) {
            console.error("Confirm Import Error:", err);
            // Pastikan error dikonversi ke string agar tidak tampil [object Object]
            const msg = err instanceof Error ? err.message : (typeof err === 'string' ? err : JSON.stringify(err));
            alert("Gagal menyimpan ke database:\n" + msg);
        } finally {
            setImportLoading(false);
        }
    };

    const SortIcon = ({ col }: { col: keyof Warga | 'address' }) => {
        if (sortConfig.key !== col) return <i className="fa-solid fa-sort opacity-20 ml-1"></i>;
        return sortConfig.direction === 'asc' 
            ? <i className="fa-solid fa-arrow-up-z-a text-primary ml-1"></i> 
            : <i className="fa-solid fa-arrow-down-z-a text-primary ml-1"></i>;
    };

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-200/60 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 tracking-tight">Data Warga</h1>
                    <p className="text-slate-500 text-sm font-medium">Manajemen profil warga desa Rowosari.</p>
                </div>
                <div className="flex flex-wrap gap-2 w-full md:w-auto">
                    <input type="file" ref={fileInputRef} onChange={handleFileSelect} accept=".xlsx, .xls" className="hidden" />
                    <button onClick={handleDownloadTemplate} className="flex-1 md:flex-none bg-slate-50 text-slate-600 px-4 py-2.5 rounded-xl font-bold hover:bg-slate-100 transition-all flex items-center justify-center gap-2 border border-slate-200 text-xs">
                        <FileExcelIcon className="text-emerald-500" /> Template
                    </button>
                    <button onClick={() => fileInputRef.current?.click()} disabled={importLoading} className="flex-1 md:flex-none bg-slate-800 text-white px-4 py-2.5 rounded-xl font-bold hover:bg-slate-900 transition-all flex items-center justify-center gap-2 text-xs">
                        <UploadIcon /> {importLoading ? 'Membaca...' : 'Import Excel'}
                    </button>
                    <button onClick={() => { setSelectedWarga(null); setIsFormModalOpen(true); }} className="flex-1 md:flex-none bg-primary text-white px-5 py-2.5 rounded-xl font-bold hover:bg-primary-focus shadow-lg shadow-primary/20 transition-all text-sm">
                      + Tambah Warga
                    </button>
                </div>
            </div>

            <div className="bg-white p-5 rounded-3xl border border-slate-200/60 shadow-sm space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="relative md:col-span-2">
                        <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input type="text" placeholder="Cari nama atau ID..." className="w-full pl-11 pr-4 py-3 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none bg-slate-50 font-semibold" value={filters.search} onChange={e => setFilters({...filters, search: e.target.value})} />
                    </div>
                    <select className="px-4 py-3 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none bg-slate-50 font-bold text-slate-600" onChange={e => setFilters({...filters, dukuhId: e.target.value})} value={filters.dukuhId}>
                        <option value="all">Semua Dukuh</option>
                        {dukuhList.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                    </select>
                    <select className="px-4 py-3 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none bg-slate-50 font-bold text-slate-600" onChange={e => setFilters({...filters, rtId: e.target.value})} value={filters.rtId}>
                        <option value="all">Semua RT</option>
                        {rtList.map(rt => <option key={rt.id} value={rt.id}>RT {rt.number}</option>)}
                    </select>
                </div>

                <div className="flex items-center justify-between border-t border-slate-100 pt-3">
                    <div className="flex items-center gap-3">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest whitespace-nowrap">Baris Per Halaman</span>
                        <select value={itemsPerPage} onChange={e => { setItemsPerPage(e.target.value === 'all' ? 'all' : Number(e.target.value)); setCurrentPage(1); }} className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold text-slate-700 outline-none">
                            <option value={10}>10</option><option value={25}>25</option><option value="all">Semua</option>
                        </select>
                    </div>
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Ditemukan {sortedAndFilteredWarga.length} Warga</p>
                </div>
            </div>

            <div className="bg-white rounded-[2.5rem] border border-slate-200/60 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left">
                        <thead>
                            <tr className="bg-slate-50/50 border-b border-slate-100 font-bold text-slate-400 uppercase text-[10px] tracking-widest">
                                <th onClick={() => handleSort('id')} className="p-5 cursor-pointer hover:text-primary transition-colors whitespace-nowrap">ID <SortIcon col="id" /></th>
                                <th onClick={() => handleSort('name')} className="p-5 cursor-pointer hover:text-primary transition-colors">Nama Lengkap <SortIcon col="name" /></th>
                                <th onClick={() => handleSort('address')} className="p-5 cursor-pointer hover:text-primary transition-colors">Wilayah (RT/Dukuh) <SortIcon col="address" /></th>
                                <th onClick={() => handleSort('dailyFee')} className="p-5 text-right cursor-pointer hover:text-primary transition-colors whitespace-nowrap">Tarif Iuran <SortIcon col="dailyFee" /></th>
                                <th className="p-5 text-center">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading ? <tr><td colSpan={5} className="p-10 text-center animate-pulse font-bold text-slate-300 uppercase tracking-widest text-xs">Memuat data Warga...</td></tr> : 
                            paginatedWarga.map(w => (
                                <tr key={w.id} className="hover:bg-slate-50/50 transition-colors">
                                    <td className="p-5 text-xs font-bold text-slate-400 font-mono tracking-tighter">{(w.id || 'N/A')}</td>
                                    <td className="p-5 font-bold text-slate-700">{(w.name || 'Warga Tanpa Nama')}</td>
                                    <td className="p-5 text-slate-500 font-medium text-xs">RT {rtList.find(r => r.id === w.rtId)?.number || '?'}, {dukuhList.find(d => d.id === w.dukuhId)?.name || '?'}</td>
                                    <td className="p-5 text-right font-bold text-slate-700 font-mono tracking-tighter">Rp{(w.dailyFee || 0).toLocaleString('id-ID')}</td>
                                    <td className="p-5">
                                        <div className="flex justify-center items-center gap-1">
                                            <button onClick={() => setQrToShow(w)} className="p-2 text-slate-400 hover:text-emerald-500 hover:bg-emerald-50 rounded-xl transition-all" title="QR Code"><QrCodeIcon className="text-xl" /></button>
                                            <button onClick={() => { setSelectedWarga(w); setIsFormModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-500 hover:bg-indigo-50 rounded-xl transition-all" title="Edit"><PencilIcon className="text-xl" /></button>
                                            <button onClick={() => setWargaToDelete(w)} className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all" title="Hapus"><TrashIcon className="text-xl" /></button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* MODAL: FORM ADD/EDIT */}
            <Modal isOpen={isFormModalOpen} onClose={() => setIsFormModalOpen(false)} title={selectedWarga ? 'Edit Warga' : 'Tambah Warga'} size="lg">
                <WargaForm warga={selectedWarga} dukuhList={dukuhList} rtList={rtList} onSave={async (d) => { if ('id' in d) await updateWarga(d.id, d as Warga); else await createWarga(d); fetchData(); setIsFormModalOpen(false); }} onCancel={() => setIsFormModalOpen(false)} />
            </Modal>

            {/* MODAL: REVIEW IMPORT EXCEL */}
            <Modal isOpen={!!importReview} onClose={() => setImportReview(null)} title="Review Import Excel" size="lg">
                {importReview && (
                    <div className="space-y-6">
                        <div className="grid grid-cols-3 gap-4">
                            <div className="bg-slate-50 p-4 rounded-2xl text-center border border-slate-200">
                                <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Total Baris</p>
                                <p className="text-2xl font-black text-slate-800">{importReview.total}</p>
                            </div>
                            <div className="bg-emerald-50 p-4 rounded-2xl text-center border border-emerald-100">
                                <p className="text-[10px] font-black text-emerald-600 uppercase mb-1">Siap Impor</p>
                                <p className="text-2xl font-black text-emerald-700">{importReview.valid.length}</p>
                            </div>
                            <div className="bg-rose-50 p-4 rounded-2xl text-center border border-rose-100">
                                <p className="text-[10px] font-black text-rose-600 uppercase mb-1">Dilewati</p>
                                <p className="text-2xl font-black text-rose-700">{importReview.invalidCount}</p>
                            </div>
                        </div>

                        {(importReview.invalidCount > 0 || importReview.idErrors) && (
                            <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100 flex items-start gap-3">
                                <i className="fa-solid fa-triangle-exclamation text-amber-500 mt-1"></i>
                                <div>
                                    <p className="text-xs text-amber-800 leading-relaxed font-bold uppercase mb-1">Beberapa Data Tidak Valid</p>
                                    <p className="text-xs text-amber-700 leading-relaxed">
                                        {importReview.idErrors 
                                            ? "Masalah Utama: Beberapa Kode Dukuh atau Kode RT di Excel tidak ditemukan di database. Pastikan wilayah sudah didaftarkan di menu 'Data Wilayah' sebelum impor."
                                            : "Pastikan judul kolom sesuai: Nama, Tarif, Kode Dukuh, Kode RT. Baris dengan data kosong akan otomatis dilewati."
                                        }
                                    </p>
                                </div>
                            </div>
                        )}

                        <div className="max-h-60 overflow-y-auto border border-slate-100 rounded-2xl">
                            <table className="w-full text-xs text-left">
                                <thead className="bg-slate-50 sticky top-0 font-bold text-slate-500">
                                    <tr>
                                        <th className="p-3">Nama (Hasil Baca)</th>
                                        <th className="p-3">Wilayah</th>
                                        <th className="p-3 text-right">Tarif</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-50">
                                    {importReview.valid.length > 0 ? importReview.valid.slice(0, 20).map((w, i) => (
                                        <tr key={i}>
                                            <td className="p-3 font-semibold text-slate-700">{w.name}</td>
                                            <td className="p-3 text-slate-500">
                                                RT {rtList.find(r => r.id === Number(w.rtId))?.number || '?'}, {dukuhList.find(d => d.id === Number(w.dukuhId))?.name || 'ID ' + w.dukuhId + ' Tidak Ada'}
                                            </td>
                                            <td className="p-3 text-right font-mono text-slate-500">Rp{(w.dailyFee || 0).toLocaleString('id-ID')}</td>
                                        </tr>
                                    )) : (
                                        <tr><td colSpan={3} className="p-10 text-center text-slate-400 italic">Tidak ada data yang valid untuk diimpor. Periksa kembali file Excel Anda.</td></tr>
                                    )}
                                    {importReview.valid.length > 20 && (
                                        <tr><td colSpan={3} className="p-3 text-center text-slate-400 italic font-medium">...dan {importReview.valid.length - 20} data lainnya</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>

                        <div className="flex gap-3 pt-4">
                            <button onClick={() => setImportReview(null)} className="flex-1 py-4 rounded-2xl font-bold text-slate-500 bg-slate-100 hover:bg-slate-200 transition-all">Batal</button>
                            <button 
                                onClick={confirmImport} 
                                disabled={importLoading || importReview.valid.length === 0} 
                                className="flex-[2] py-4 rounded-2xl font-bold bg-emerald-500 text-white shadow-xl shadow-emerald-500/20 hover:bg-emerald-600 transition-all flex items-center justify-center gap-2 disabled:bg-slate-300 disabled:shadow-none"
                            >
                                {importLoading ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : <CheckCircleIcon />}
                                Simpan ke Database
                            </button>
                        </div>
                    </div>
                )}
            </Modal>

            <Modal isOpen={!!qrToShow} onClose={() => setQrToShow(null)} title="Kartu Warga (Barcode)">
                {qrToShow && (
                    <div className="text-center py-6 flex flex-col items-center">
                        <div className="p-8 bg-white border-2 border-slate-100 rounded-[2.5rem] shadow-sm mb-6 flex flex-col items-center w-full max-w-xs">
                            <div className="bg-emerald-500 w-full h-12 -mt-8 -mx-8 mb-6 rounded-t-[2.5rem] flex items-center justify-center">
                              <span className="text-white font-black uppercase tracking-widest text-xs">SAPADESA CARD</span>
                            </div>
                            <QRCodeSVG value={qrToShow.id || ''} size={180} />
                            <h4 className="text-xl font-black text-slate-800 uppercase tracking-tight mt-6">{(qrToShow.name || 'N/A')}</h4>
                            <p className="text-sm font-bold text-slate-400 mt-1">ID: {(qrToShow.id || 'N/A')}</p>
                        </div>
                        <button onClick={() => window.print()} className="w-full py-4 rounded-2xl bg-slate-800 text-white font-bold flex items-center justify-center gap-2 shadow-lg hover:bg-slate-900 transition-all"><DownloadIcon /> Unduh / Cetak Slip</button>
                    </div>
                )}
            </Modal>

            <Modal isOpen={!!wargaToDelete} onClose={() => setWargaToDelete(null)} title="Hapus Data">
                {wargaToDelete && (
                    <div className="text-center py-4">
                        <div className="w-20 h-20 bg-rose-50 rounded-3xl flex items-center justify-center mx-auto mb-6"><TrashIcon className="text-4xl text-rose-500" /></div>
                        <p className="font-bold text-slate-800 text-lg px-4">Hapus warga <span className="text-rose-600">"{(wargaToDelete.name || 'Warga Terpilih')}"</span>?</p>
                        <div className="mt-10 flex gap-3 px-2">
                            <button onClick={() => setWargaToDelete(null)} className="flex-1 py-4 rounded-2xl text-slate-500 font-bold hover:bg-slate-100">Batal</button>
                            <button onClick={async () => { await deleteWarga(wargaToDelete.id); fetchData(); setWargaToDelete(null); }} className="flex-1 py-4 rounded-2xl bg-rose-500 text-white font-bold shadow-lg shadow-rose-500/20">Hapus</button>
                        </div>
                    </div>
                )}
            </Modal>
        </div>
    );
};

export default AdminWargaPage;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { getReports, deleteTransaksi, getAllDukuh, getAllRT } from '@/services/api';
import type { Transaksi, Dukuh, RT } from '@/types';
import { SearchIcon, ClipboardListIcon, TrashIcon, ChevronDownIcon, DownloadIcon, BanknotesIcon, CurrencyDollarIcon } from '@/components/icons';
import Modal from '@/components/Modal';

interface ReportRow extends Transaksi {
    wargaName: string;
    petugasName: string;
    dukuhName: string;
    rtNumber: string;
}

const AdminRiwayatTransaksiPage: React.FC = () => {
    const [transactions, setTransactions] = useState<ReportRow[]>([]);
    const [dukuhList, setDukuhList] = useState<Dukuh[]>([]);
    const [rtList, setRtList] = useState<RT[]>([]);
    const [loading, setLoading] = useState(true);
    const [transactionToDelete, setTransactionToDelete] = useState<ReportRow | null>(null);

    // Filters & Sorting
    const [filters, setFilters] = useState({
        startDate: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        search: '',
        dukuhId: 'all',
        rtId: 'all',
        category: 'all' // New Filter
    });
    const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({ key: 'timestamp', direction: 'desc' });
    const [itemsPerPage, setItemsPerPage] = useState<number | 'all'>(10);
    const [currentPage, setCurrentPage] = useState(1);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [data, d, r] = await Promise.all([
                getReports({ startDate: new Date(filters.startDate), endDate: new Date(filters.endDate) }),
                getAllDukuh(),
                getAllRT()
            ]);
            setTransactions(data);
            setDukuhList(d);
            setRtList(r);
        } catch (error) {
            console.error("Failed to fetch transactions", error);
        } finally {
            setLoading(false);
        }
    }, [filters.startDate, filters.endDate]);

    useEffect(() => { fetchData(); }, [fetchData]);

    const requestSort = (key: string) => {
        let direction: 'asc' | 'desc' = 'asc';
        if (sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
        setSortConfig({ key, direction });
    };

    const sortedAndFilteredTx = useMemo(() => {
        let items = transactions.filter(tx => {
            const query = (filters.search || '').toLowerCase();
            const matchSearch = (tx.wargaName || '').toLowerCase().includes(query) || (tx.id || '').toLowerCase().includes(query);
            const matchDukuh = filters.dukuhId === 'all' || tx.dukuhName === dukuhList.find(d => d.id === Number(filters.dukuhId))?.name;
            const matchRT = filters.rtId === 'all' || tx.rtNumber === rtList.find(r => r.id === Number(filters.rtId))?.number;
            const matchCategory = filters.category === 'all' || tx.category === filters.category;
            return matchSearch && matchDukuh && matchRT && matchCategory;
        });

        items.sort((a, b) => {
            let aVal: any, bVal: any;
            switch(sortConfig.key) {
                case 'warga': aVal = (a.wargaName || ''); bVal = (b.wargaName || ''); break;
                case 'petugas': aVal = (a.petugasName || ''); bVal = (b.petugasName || ''); break;
                case 'amount': aVal = (a.amount || 0); bVal = (b.amount || 0); break;
                case 'category': aVal = (a.category || ''); bVal = (b.category || ''); break;
                case 'wilayah': aVal = (a.dukuhName || '') + (a.rtNumber || ''); bVal = (b.dukuhName || '') + (b.rtNumber || ''); break;
                default: aVal = a.timestamp ? new Date(a.timestamp).getTime() : 0; bVal = b.timestamp ? new Date(b.timestamp).getTime() : 0;
            }
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
        return items;
    }, [transactions, filters, sortConfig, dukuhList, rtList]);

    const paginatedTx = useMemo(() => {
        if (itemsPerPage === 'all') return sortedAndFilteredTx;
        const start = (currentPage - 1) * (itemsPerPage as number);
        return sortedAndFilteredTx.slice(start, start + (itemsPerPage as number));
    }, [sortedAndFilteredTx, itemsPerPage, currentPage]);

    const totalPages = itemsPerPage === 'all' ? 1 : Math.ceil(sortedAndFilteredTx.length / (itemsPerPage as number));

    const handlePrint = () => {
        const printWindow = window.open('', '_blank');
        if (!printWindow) return;
        const rows = sortedAndFilteredTx.map(tx => `
            <tr>
                <td>${tx.timestamp ? new Date(tx.timestamp).toLocaleDateString('id-ID') : 'N/A'}</td>
                <td><div style="font-weight:700;">${tx.wargaName || 'Warga Terhapus'}</div><div style="font-size:7pt; color:#64748b;">ID: ${tx.wargaId || 'N/A'}</div></td>
                <td>RT ${tx.rtNumber || '?'}, ${tx.dukuhName || 'N/A'}</td>
                <td><span style="font-size:8pt; font-weight:800; color:${tx.category === 'TUNGGAKAN' ? '#6366f1' : '#10b981'}">${tx.category || 'IURAN'}</span></td>
                <td>${tx.petugasName || 'N/A'}</td>
                <td style="text-align:right; font-weight:700;">Rp${(tx.amount || 0).toLocaleString('id-ID')}</td>
            </tr>
        `).join('');

        printWindow.document.write(`
            <html>
            <head>
                <style>
                    @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800&display=swap');
                    @page { size: A4; margin: 1cm; }
                    body { font-family: 'Plus Jakarta Sans', sans-serif; color: #1e293b; margin: 0; padding: 0; }
                    .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #0f172a; padding-bottom: 10px; margin-bottom: 25px; }
                    .header-left .logo { color: #10b981; font-size: 24pt; font-weight: 800; margin: 0; line-height: 1.1; }
                    .header-left .sub-1 { font-size: 9pt; font-weight: 700; color: #1e293b; margin: 5px 0 0 0; text-transform: uppercase; }
                    .header-left .sub-2 { font-size: 7.5pt; font-weight: 500; color: #64748b; margin: 2px 0 0 0; text-transform: uppercase; }
                    .header-right { text-align: right; }
                    .report-title { font-size: 12pt; font-weight: 800; text-transform: uppercase; color: #1e293b; margin: 0; }
                    .print-date { font-size: 8pt; color: #94a3b8; font-weight: 600; margin-top: 4px; }

                    table { width: 100%; border-collapse: collapse; margin-top: 15px; }
                    th { background: #f8fafc; text-align: left; padding: 12px; font-size: 8.5pt; text-transform: uppercase; border-bottom: 1.5px solid #e2e8f0; color: #475569; }
                    td { padding: 12px; border-bottom: 1px solid #f1f5f9; font-size: 9.5pt; }
                </style>
            </head>
            <body>
                <div class="header">
                    <div class="header-left">
                        <h1 class="logo">SAPADESA</h1>
                        <p class="sub-1">PENGELOLAAN SAMPAH DESA ROWOSARI, BATANG</p>
                        <p class="sub-2">SEKRETARIAT: KANTOR DESA ROWOSARI, JAWA TENGAH 51271</p>
                    </div>
                    <div class="header-right">
                        <div class="report-title">Laporan Riwayat Transaksi</div>
                        <div class="print-date">PERIODE: ${filters.startDate} - ${filters.endDate}</div>
                        <div class="print-date">WAKTU CETAK: ${new Date().toLocaleString('id-ID')}</div>
                    </div>
                </div>
                <table>
                    <thead><tr><th>Tanggal</th><th>Warga</th><th>Wilayah</th><th>Kategori</th><th>Petugas</th><th style="text-align:right">Jumlah</th></tr></thead>
                    <tbody>${rows || '<tr><td colspan="6" style="text-align:center; padding: 20px;">Tidak ditemukan data transaksi sesuai filter</td></tr>'}</tbody>
                </table>
                <script>window.onload=()=>{window.print();window.close();}</script>
            </body>
            </html>
        `);
        printWindow.document.close();
    };

    const SortIcon = ({ column }: { column: string }) => {
        if (sortConfig.key !== column) return <ChevronDownIcon className="ml-1 opacity-20" />;
        return sortConfig.direction === 'asc' 
            ? <i className="fa-solid fa-sort-up ml-1 text-primary"></i> 
            : <i className="fa-solid fa-sort-down ml-1 text-primary"></i>;
    };

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 tracking-tight font-display">Riwayat Transaksi</h1>
                    <p className="mt-1 text-slate-500 text-sm font-medium">Monitoring seluruh aliran dana retribusi warga.</p>
                </div>
                <button onClick={handlePrint} className="w-full md:w-auto bg-slate-800 text-white font-bold px-6 py-3 rounded-xl shadow-lg hover:bg-slate-900 transition-all flex items-center justify-center gap-2">
                    <DownloadIcon /> Cetak Laporan
                </button>
            </div>

            <div className="bg-white p-4 rounded-3xl border border-slate-200 shadow-sm space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-3">
                    <div className="bg-slate-50/50 p-2 rounded-xl border border-slate-100">
                        <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Dari</label>
                        <input type="date" value={filters.startDate} onChange={e => setFilters({...filters, startDate: e.target.value})} className="w-full bg-transparent font-bold text-xs outline-none" />
                    </div>
                    <div className="bg-slate-50/50 p-2 rounded-xl border border-slate-100">
                        <label className="block text-[10px] font-black text-slate-400 uppercase mb-1">Sampai</label>
                        <input type="date" value={filters.endDate} onChange={e => setFilters({...filters, endDate: e.target.value})} className="w-full bg-transparent font-bold text-xs outline-none" />
                    </div>
                    <select className="px-3 py-2 border border-slate-200 rounded-xl font-bold text-xs bg-slate-50/50" onChange={e => setFilters({...filters, category: e.target.value})} value={filters.category}>
                        <option value="all">Semua Jenis</option>
                        <option value="IURAN">Iuran Harian</option>
                        <option value="TUNGGAKAN">Bayar Tunggakan</option>
                    </select>
                    <select className="px-3 py-2 border border-slate-200 rounded-xl font-bold text-xs bg-slate-50/50" onChange={e => setFilters({...filters, dukuhId: e.target.value})} value={filters.category}>
                        <option value="all">Semua Dukuh</option>
                        {dukuhList.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                    </select>
                    <select className="px-3 py-2 border border-slate-200 rounded-xl font-bold text-xs bg-slate-50/50" onChange={e => setFilters({...filters, rtId: e.target.value})} value={filters.rtId}>
                        <option value="all">Semua RT</option>
                        {rtList.map(rt => <option key={rt.id} value={rt.id}>RT {rt.number}</option>)}
                    </select>
                    <div className="relative">
                        <input type="text" placeholder="Cari warga/petugas..." value={filters.search} onChange={e => setFilters({...filters, search: e.target.value})} className="w-full pl-8 pr-4 py-3 border border-slate-200 rounded-xl text-xs font-medium bg-slate-50/50 outline-none" />
                        <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs" />
                    </div>
                </div>

                <div className="flex items-center justify-between border-t border-slate-100 pt-3">
                    <div className="flex items-center gap-3">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tampilkan</span>
                        <select value={itemsPerPage} onChange={e => { setItemsPerPage(e.target.value === 'all' ? 'all' : Number(e.target.value)); setCurrentPage(1); }} className="bg-white border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-bold text-slate-700 outline-none focus:ring-2 focus:ring-primary/20">
                            <option value={10}>10 Baris</option>
                            <option value={25}>25 Baris</option>
                            <option value={50}>50 Baris</option>
                            <option value="all">Semua</option>
                        </select>
                    </div>
                    <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Total {sortedAndFilteredTx.length} Transaksi</div>
                </div>
            </div>

            <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left font-sans">
                        <thead>
                            <tr className="bg-slate-50/50 border-b border-slate-100 text-slate-400 uppercase text-[10px] font-black tracking-widest">
                                <th onClick={() => requestSort('timestamp')} className="p-4 cursor-pointer hover:bg-slate-100 transition-all w-32"><div className="flex items-center">Waktu <SortIcon column="timestamp" /></div></th>
                                <th onClick={() => requestSort('warga')} className="p-4 cursor-pointer hover:bg-slate-100 transition-all"><div className="flex items-center">Warga <SortIcon column="warga" /></div></th>
                                <th onClick={() => requestSort('category')} className="p-4 cursor-pointer hover:bg-slate-100 transition-all text-center"><div className="flex items-center justify-center">Kategori <SortIcon column="category" /></div></th>
                                <th onClick={() => requestSort('wilayah')} className="p-4 cursor-pointer hover:bg-slate-100 transition-all"><div className="flex items-center">Wilayah <SortIcon column="wilayah" /></div></th>
                                <th onClick={() => requestSort('petugas')} className="p-4 cursor-pointer hover:bg-slate-100 transition-all"><div className="flex items-center">Petugas <SortIcon column="petugas" /></div></th>
                                <th onClick={() => requestSort('amount')} className="p-4 text-right cursor-pointer hover:bg-slate-100 transition-all"><div className="flex items-center justify-end">Jumlah <SortIcon column="amount" /></div></th>
                                <th className="p-4 text-center">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading ? <tr><td colSpan={7} className="p-10 text-center animate-pulse">Memuat data transaksi...</td></tr> : 
                            paginatedTx.map(tx => (
                                <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors group">
                                    <td className="p-4 text-xs font-medium text-slate-500">
                                        <div className="font-bold text-slate-700">{tx.timestamp ? new Date(tx.timestamp).toLocaleDateString('id-ID', { day:'2-digit', month:'short' }) : 'N/A'}</div>
                                        <div className="text-[10px] text-slate-400 font-mono">{tx.timestamp ? new Date(tx.timestamp).toLocaleTimeString('id-ID', {hour:'2-digit', minute:'2-digit'}) : '--:--'}</div>
                                    </td>
                                    <td className="p-4">
                                        <div className="font-bold text-slate-700 group-hover:text-primary transition-colors">{(tx.wargaName || 'Warga Terhapus')}</div>
                                        <div className="text-[10px] text-slate-400 font-mono">ID: {(tx.wargaId || 'N/A')}</div>
                                    </td>
                                    <td className="p-4 text-center">
                                        {tx.category === 'TUNGGAKAN' ? (
                                            <span className="inline-flex items-center gap-1 bg-indigo-50 text-indigo-600 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter border border-indigo-100">
                                                <BanknotesIcon className="text-[10px]" /> Tunggakan
                                            </span>
                                        ) : (
                                            <span className="inline-flex items-center gap-1 bg-emerald-50 text-emerald-600 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter border border-emerald-100">
                                                <CurrencyDollarIcon className="text-[10px]" /> Iuran
                                            </span>
                                        )}
                                    </td>
                                    <td className="p-4 text-xs text-slate-500 font-medium">RT {(tx.rtNumber || '?')}, {(tx.dukuhName || 'N/A')}</td>
                                    <td className="p-4 text-slate-600 font-medium text-[10px] uppercase tracking-wider">{(tx.petugasName || 'N/A')}</td>
                                    <td className="p-4 text-right font-mono font-black text-emerald-600 text-base">Rp{(tx.amount || 0).toLocaleString('id-ID')}</td>
                                    <td className="p-4 text-center">
                                        <button onClick={() => setTransactionToDelete(tx)} className="text-slate-300 hover:text-rose-500 p-2 rounded-lg transition-all" title="Hapus"><TrashIcon /></button>
                                    </td>
                                </tr>
                            ))}
                            {!loading && sortedAndFilteredTx.length === 0 && (
                                <tr><td colSpan={7} className="p-12 text-center text-slate-400 font-bold italic text-xs uppercase">Tidak ada data transaksi yang ditemukan</td></tr>
                            )}
                        </tbody>
                    </table>
                </div>

                {itemsPerPage !== 'all' && totalPages > 1 && (
                    <div className="p-5 bg-slate-50/30 border-t border-slate-100 flex justify-center items-center">
                        <div className="flex items-center gap-1 font-bold text-sm">
                            <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="p-2 disabled:opacity-20 text-slate-400 hover:text-primary transition-colors"><i className="fa-solid fa-chevron-left"></i></button>
                            <span className="bg-primary text-white w-8 h-8 flex items-center justify-center rounded-lg shadow-sm text-xs">{currentPage}</span>
                            <span className="px-2 text-slate-400 font-medium text-xs">/ {totalPages}</span>
                            <button onClick={() => setCurrentPage(p => Math.min(totalPages, p+1))} disabled={currentPage === totalPages} className="p-2 disabled:opacity-20 text-slate-400 hover:text-primary transition-colors"><i className="fa-solid fa-chevron-right"></i></button>
                        </div>
                    </div>
                )}
            </div>

            <Modal isOpen={!!transactionToDelete} onClose={() => setTransactionToDelete(null)} title="Hapus Transaksi">
                {transactionToDelete && (
                    <div className="text-center">
                        <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-4 text-rose-500">
                          <TrashIcon className="text-3xl" />
                        </div>
                        <p className="font-bold text-slate-800 text-lg">Hapus riwayat transaksi ini?</p>
                        <p className="text-xs text-slate-400 mt-2 px-6">Tindakan ini akan mempengaruhi laporan saldo keuangan desa secara permanen.</p>
                        <div className="mt-8 flex gap-3">
                            <button onClick={() => setTransactionToDelete(null)} className="flex-1 py-4 font-bold text-slate-500 bg-slate-50 rounded-2xl hover:bg-slate-100 transition-all">Batal</button>
                            <button onClick={async () => { await deleteTransaksi(transactionToDelete.id); fetchData(); setTransactionToDelete(null); }} className="flex-1 py-4 font-bold bg-rose-500 text-white rounded-2xl shadow-lg shadow-rose-500/20 hover:bg-rose-600 transition-all">Ya, Hapus</button>
                        </div>
                    </div>
                )}
            </Modal>
        </div>
    );
};

export default AdminRiwayatTransaksiPage;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import type { Pengeluaran } from '@/types';
import { getPengeluaran, createPengeluaran, updatePengeluaran, deletePengeluaran, getAdminDashboardStats } from '@/services/api';
import Modal from '@/components/Modal';
import { TrashIcon, PencilIcon, BanknotesIcon, SearchIcon, DownloadIcon, ScaleBalancedIcon, CurrencyDollarIcon, XIcon } from '@/components/icons';

const PengeluaranForm: React.FC<{
  pengeluaran?: Pengeluaran | null;
  onSave: (p: Omit<Pengeluaran, 'id'> | Pengeluaran) => void;
  onCancel: () => void;
}> = ({ pengeluaran, onSave, onCancel }) => {
  const [formData, setFormData] = useState({
    date: pengeluaran?.date ? new Date(pengeluaran.date).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
    description: pengeluaran?.description || '',
    amount: pengeluaran?.amount || 0,
  });

  // Handler untuk format nominal uang (titik ribuan dan hapus nol depan)
  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, '');
    if (raw.startsWith('0') && raw.length > 1) raw = raw.replace(/^0+/, '');
    const val = raw === '' ? 0 : Number(raw);
    setFormData({ ...formData, amount: val });
  };

  const displayAmount = formData.amount === 0 ? '' : formData.amount.toLocaleString('id-ID');

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSave(pengeluaran ? { ...pengeluaran, ...formData, date: new Date(formData.date) } : { ...formData, date: new Date(formData.date) }); }} className="space-y-6">
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tanggal Transaksi</label>
        <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-semibold text-slate-700" required />
      </div>
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Keterangan / Keperluan</label>
        <input type="text" placeholder="Contoh: Pembelian Bensin Tossa, Gaji Petugas, dsb" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-semibold text-slate-700" required />
      </div>
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Jumlah Nominal (Pengeluaran)</label>
        <div className="relative group">
            <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-slate-400 group-focus-within:text-rose-500 transition-colors">Rp</span>
            <input 
                type="text" 
                inputMode="numeric"
                value={displayAmount} 
                onChange={handleAmountChange} 
                placeholder="0"
                className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-rose-500 outline-none font-black text-rose-600 text-lg" 
                required 
            />
        </div>
        <p className="text-[10px] text-slate-400 italic ml-1">* Masukkan nominal tanpa titik/koma</p>
      </div>
      <div className="flex gap-3 pt-4">
        <button type="button" onClick={onCancel} className="flex-1 py-4 rounded-2xl font-bold text-slate-500 bg-slate-50 hover:bg-slate-100 transition-all">Batal</button>
        <button type="submit" className="flex-1 py-4 rounded-2xl font-bold bg-slate-900 text-white hover:bg-black shadow-xl shadow-slate-900/20 transition-all">Simpan Catatan</button>
      </div>
    </form>
  );
};

