                    <div className="mt-4 pt-4 border-t border-slate-200">
                        <p className="text-sm text-slate-500">
                            Jadwal hari ini: 
                            <span className="font-semibold text-slate-700 ml-1">
                                {scheduleInfo.isHoliday ? 'Libur' : (scheduleInfo.dukuhNames || []).join(', ')}
