    }));

    const { error } = await supabase.from('wargas').insert(payload);

    if (error) {
        console.error("Supabase bulk insert full error:", error);
        let msg = error.message;
        if (error.code === '23503') {
            msg = "Gagal: Salah satu Kode Dukuh atau Kode RT tidak terdaftar di sistem.";
        } else if (error.code === '23505') {
            msg = "Gagal: Terjadi duplikasi ID sistem secara acak.";
