interface ReportRow extends Transaksi {
    wargaName: string;
    petugasName: string;
    dukuhName: string;
    rtNumber: string;
    wargaDukuhId?: number;
    wargaRtId?: number;
}

const AdminRiwayatTransaksiPage: React.FC = () => {
    const [transactions, setTransactions] = useState<ReportRow[]>([]);
    const [dukuhList, setDukuhList] = useState<Dukuh[]>([]);
    const [rtList, setRtList] = useState<RT[]>([]);
    const [loading, setLoading] = useState(true);
    const [transactionToDelete, setTransactionToDelete] = useState<ReportRow | null>(null);

    const [filters, setFilters] = useState({
        startDate: new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0],
        endDate: new Date().toISOString().split('T')[0],
        search: '',
        dukuhId: 'all',
        rtId: 'all',
        category: 'all'
    });

    const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({ key: 'timestamp', direction: 'desc' });
    const [itemsPerPage, setItemsPerPage] = useState<number | 'all'>(10);
    const [currentPage, setCurrentPage] = useState(1);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [data, d, r] = await Promise.all([
                getReports({ startDate: new Date(filters.startDate), endDate: new Date(filters.endDate) }),
                getAllDukuh(),
                getAllRT()
            ]);
            setTransactions(data);
            setDukuhList(d);
            setRtList(r);
        } catch (error) {
            console.error("Failed to fetch transactions", error);
        } finally {
            setLoading(false);
        }
    }, [filters.startDate, filters.endDate]);

    useEffect(() => { fetchData(); }, [fetchData]);

    const requestSort = (key: string) => {
        let direction: 'asc' | 'desc' = 'asc';
        if (sortConfig.key === key && sortConfig.direction === 'asc') direction = 'desc';
        setSortConfig({ key, direction });
    };

    const sortedAndFilteredTx = useMemo(() => {
        let items = transactions.filter(tx => {
            const query = (filters.search || '').toLowerCase();
            const matchSearch = (tx.wargaName || '').toLowerCase().includes(query) || (tx.id || '').toLowerCase().includes(query) || (tx.wargaId || '').toLowerCase().includes(query);

            // Filter berdasarkan ID Wilayah untuk akurasi lebih baik
            const wargaObj = (tx as any).wargas;
            const txDukuhId = wargaObj?.dukuhId;
            const txRtId = wargaObj?.rtId;

            const matchDukuh = filters.dukuhId === 'all' || String(txDukuhId) === String(filters.dukuhId);
            const matchRT = filters.rtId === 'all' || String(txRtId) === String(filters.rtId);
            const matchCategory = filters.category === 'all' || tx.category === filters.category;

            return matchSearch && matchDukuh && matchRT && matchCategory;
        });

        items.sort((a, b) => {
            let aVal: any, bVal: any;
            switch(sortConfig.key) {
                case 'warga': aVal = (a.wargaName || ''); bVal = (b.wargaName || ''); break;
                case 'petugas': aVal = (a.petugasName || ''); bVal = (b.petugasName || ''); break;
                case 'amount': aVal = (a.amount || 0); bVal = (b.amount || 0); break;
                case 'category': aVal = (a.category || ''); bVal = (b.category || ''); break;
                case 'wilayah': aVal = (a.dukuhName || '') + (a.rtNumber || ''); bVal = (b.dukuhName || '') + (b.rtNumber || ''); break;
                default: aVal = a.timestamp ? new Date(a.timestamp).getTime() : 0; bVal = b.timestamp ? new Date(b.timestamp).getTime() : 0;
            }
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
        return items;
    }, [transactions, filters, sortConfig]);

