    const totalExpense = (expense || []).reduce((s, i) => s + i.amount, 0);
    const totalDebt = (wargas || []).reduce((s, w) => s + (w.totalDebt || 0), 0);

    return {
        totalRevenue,
        totalExpense,
        balance: totalRevenue - totalExpense,
        totalWarga: wargas?.length || 0,
        totalDebt
    };
};

