export const getSchedule = async () => {
    const { data } = await supabase.from('schedules').select('*');
    const result: any = {};
    (data || []).forEach(row => {
        result[row.day] = row.dukuhIds;
    });
    return result;
};

export const getScheduleForToday = async () => {
    const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
    const todayName = days[new Date().getDay()];
    const { data } = await supabase.from('schedules').select('*').eq('day', todayName).single();

    if (!data || data.dukuhIds === 'libur' || !data.dukuhIds.length) {
        return { isHoliday: true, dukuhIds: [], dukuhNames: [] };
    }

    const dukuhs = await getAllDukuh();
    const names = data.dukuhIds.map((id: number) => dukuhs.find(d => d.id === id)?.name || 'Dukuh Tak Dikenal');
    return { isHoliday: false, dukuhIds: data.dukuhIds, dukuhNames: names };
};

export const updateSchedule = async (day: string, dukuhIds: number[] | 'libur') => {
    const { error } = await supabase.from('schedules').upsert([{ day, dukuhIds }]);
    if (error) throw new Error(error.message);
};

export const markDayAsSkipped = async (dukuhIds: number[]) => {
    const { data: wargas } = await supabase.from('wargas').select('*').in('dukuhId', dukuhIds);
    if (wargas) {
        for (const w of wargas) {
            await createTransaksi({
                wargaId: w.id,
                petugasId: 'SYSTEM',
                amount: w.dailyFee,
                status: 'HUTANG',
                category: 'IURAN'
            });
        }
    }
};

export const getUnpaidWargaForToday = async (): Promise<Warga[]> => {
    const sched = await getScheduleForToday();
    if (sched.isHoliday) return [];

    const { data: allWarga } = await supabase.from('wargas').select('*').in('dukuhId', sched.dukuhIds);
    if (!allWarga) return [];

    const today = new Date();
    today.setHours(0,0,0,0);
    const { data: todayTxs } = await supabase
        .from('transactions')
        .select('wargaId')
        .gte('timestamp', today.toISOString());

    const paidIds = new Set((todayTxs || []).map(tx => tx.wargaId));

    return allWarga.filter(w => !paidIds.has(w.id));
};

export const getDetailedPublicTransparency = async (year: number) => {
    const stats = await getAdminDashboardStats();
    const dukuhs = await getAllDukuh();

    const start = new Date(year, 0, 1).toISOString();
    const end = new Date(year, 11, 31, 23, 59, 59).toISOString();

    const { data: txs } = await supabase
        .from('transactions')
        .select('amount, wargaId, timestamp')
        .eq('status', 'LUNAS')
        .gte('timestamp', start)
        .lte('timestamp', end);

    const { data: wargas } = await supabase.from('wargas').select('id, "dukuhId"');

    const dukuhStats = dukuhs.map(d => {
        const wargaInDukuh = new Set(wargas?.filter(w => w.dukuhId === d.id).map(w => w.id));
        const total = (txs || []).filter(t => wargaInDukuh.has(t.wargaId)).reduce((s, i) => s + i.amount, 0);
        return { name: d.name, total };
    });

    const monthlyStats = Array.from({ length: 12 }).map((_, i) => {
        const monthIncome = (txs || []).filter(t => new Date(t.timestamp).getMonth() === i).reduce((s, i) => s + i.amount, 0);
        return {
            monthName: new Date(year, i).toLocaleString('id-ID', { month: 'long' }),
            income: monthIncome,
            expense: 0,
            balance: monthIncome
        };
    });

    return { ...stats, dukuhStats, monthlyStats };
};

import React, { useState, useEffect, useCallback } from 'react';
import { getSchedule, updateSchedule, getAllDukuh, markDayAsSkipped, getVillageProfile, updateVillageProfile } from '@/services/api';
import Modal from '@/components/Modal';
import { PencilIcon, HomeIcon, ClockIcon, XIcon, CheckCircleIcon, PhoneIcon, EnvelopeIcon } from '@/components/icons';
import type { Dukuh, VillageProfile } from '@/types';

type Schedule = Record<string, number[] | 'libur'>;

const ScheduleForm: React.FC<{
  day: string;
  currentSchedule: number[] | 'libur';
  onSave: (day: string, newSchedule: number[] | 'libur') => void;
  onCancel: () => void;
  dukuhList: Dukuh[];
}> = ({ day, currentSchedule, onSave, onCancel, dukuhList }) => {
  const isHoliday = currentSchedule === 'libur';
  const [selectedDukuhIds, setSelectedDukuhIds] = useState<number[]>(isHoliday ? [] : (currentSchedule as number[] || []));
  const [isHolidayChecked, setIsHolidayChecked] = useState(isHoliday);

  const handleDukuhChange = (dukuhId: number) => {
    setSelectedDukuhIds(prev => {
      const current = prev || [];
      return current.includes(dukuhId) ? current.filter(id => id !== dukuhId) : [...current, dukuhId];
    });
  };

  const handleHolidayChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const checked = e.target.checked;
    setIsHolidayChecked(checked);
    if (checked) {
      setSelectedDukuhIds([]);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(day, isHolidayChecked ? 'libur' : selectedDukuhIds);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <div>
        <h3 className="text-lg font-semibold text-slate-800 mb-3">Wilayah Pengambilan - {day}</h3>
        <div className="space-y-2 max-h-60 overflow-y-auto pr-2">
            {dukuhList.map(dukuh => (
                 <label key={dukuh.id} className="flex items-center p-3 rounded-lg hover:bg-slate-100 cursor-pointer">
                    <input 
                      type="checkbox"
                      className="h-5 w-5 rounded border-slate-300 text-primary focus:ring-primary"
                      checked={selectedDukuhIds.includes(dukuh.id)}
                      onChange={() => handleDukuhChange(dukuh.id)}
                      disabled={isHolidayChecked}
                    />
                    <span className="ml-3 text-slate-700">{dukuh.name}</span>
                 </label>
            ))}
        </div>
      </div>
      <div className="border-t border-slate-200 pt-4">
         <label className="flex items-center p-3 rounded-lg hover:bg-slate-100 cursor-pointer">
            <input 
              type="checkbox"
              className="h-5 w-5 rounded border-slate-300 text-amber-500"
              checked={isHolidayChecked}
              onChange={handleHolidayChange}
            />
            <span className="ml-3 font-semibold text-slate-700">Jadikan Hari Libur</span>
         </label>
      </div>
      <div className="flex justify-end gap-3 pt-4">
        <button type="button" onClick={onCancel} className="bg-slate-200 text-slate-800 font-semibold px-4 py-2 rounded-lg">Batal</button>
        <button type="submit" className="bg-primary text-primary-content font-semibold px-4 py-2 rounded-lg">Simpan</button>
      </div>
    </form>
  );
};

